import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 15 谦：有实质而不自满至读后比较与自测","description":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","frontmatter":{"title":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 15 谦：有实质而不自满至读后比较与自测","description":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","splitFrom":"life/personal/yijing/hexagrams-09-16.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读二：小畜履泰否至同人大有谦豫","summary":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任","link":"/life/personal/yijing/hexagrams-09-16-part-02"},"next":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复","link":"/life/personal/yijing/hexagrams-17-24"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任","link":"/life/personal/yijing/hexagrams-09-16-part-02"},"next":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复","link":"/life/personal/yijing/hexagrams-17-24"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-09-16-part-03.md","filePath":"life/personal/yijing/hexagrams-09-16-part-03.md"}'),i={name:"life/personal/yijing/hexagrams-09-16-part-03.md"};function o(s,t,l,d,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读二-小畜履泰否至同人大有谦豫-·-15-谦-有实质而不自满至读后比较与自测" tabindex="-1">六十四卦详读二：小畜履泰否至同人大有谦豫 · 15 谦：有实质而不自满至读后比较与自测 <a class="header-anchor" href="#六十四卦详读二-小畜履泰否至同人大有谦豫-·-15-谦-有实质而不自满至读后比较与自测" aria-label="Permalink to &quot;六十四卦详读二：小畜履泰否至同人大有谦豫 · 15 谦：有实质而不自满至读后比较与自测&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-09-16">返回分篇目录</a></p><p>本组特别适合成对阅读：小畜与履讨论限制和行进，泰与否呈现通塞，同人与大有讨论联结和拥有，谦与豫则观察自处及群体情绪。所谓“好卦”也包含风险，“坏卦”中也可能出现可行之道。</p><p>本文逐卦对读《周易》经传与王弼注、孔颖达疏《周易正义》。引文是古籍原文，表格解释与读法为本篇白话概括；通行字句参照《正义》，如小畜的“輿說輻”、大有的“匪其彭”，并提示异文。标点属整理，不应误以为古本原有。占断是古代文化材料，本文讨论其结构与思想，不据此预测现实结果。</p><h2 id="gua-15" tabindex="-1">15 谦：有实质而不自满 <a class="header-anchor" href="#gua-15" aria-label="Permalink to &quot;15 谦：有实质而不自满 {#gua-15}&quot;">​</a></h2><p><strong>卦符：䷎　上卦：坤 ☷（地）　下卦：艮 ☶（山）。</strong></p><p><strong>卦辞原文</strong>：謙：亨，君子有終。</p><p><strong>白话概括</strong>：山有其高而处地中，谦是有实质而不占满。《正义》从先人后己、长期维持说明君子有终；它也说《易》的评价不能一律套同一规则。谦不等于自我贬低，更不等于用谦辞掩饰争名。六爻中还出现征伐，说明本卦并不是无原则退让的颂歌。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：謙謙君子，用涉大川，吉。</td><td>处下而能再谦，以此面对困难。谦并未取消行动，反能减少冒进与自恃。</td></tr><tr><td>六二：鳴謙，貞吉。</td><td>内在谦德表现于外或为人所知，守正而吉。鸣不是炫耀“我多谦虚”，须联系中心所得。</td></tr><tr><td>九三：勞謙君子，有終吉。</td><td>有劳绩而仍谦，能将事情完成。承认实际贡献与不自居功可以并存。</td></tr><tr><td>六四：无不利，撝謙。</td><td>把谦落实在行为中。撝有发挥、施行等解释，重点不只在口头礼貌。</td></tr><tr><td>六五：不富，以其鄰，利用侵伐，无不利。</td><td>不靠财富而联结邻人，并包含应对不服者的古代征伐语境。不能据此给现代私人攻击披上谦德外衣。</td></tr><tr><td>上六：鳴謙，利用行師，征邑國。</td><td>谦名已闻却仍有未尽之事，行动范围落在邑国。古注强调志未得，不宜把它当成无限向外扩张。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“地中有山，謙；君子以裒多益寡，稱物平施。”</p><p><strong>解释</strong>：裒是减取，益是增补；称量实际情况而施予，使多寡得到适当调节。谦由个人姿态延伸至分配原则，并非要求所有人的所得不分条件地完全相同。</p><p><strong>整体读法与误区</strong>：谦卦常被说成“六爻皆吉”，严格阅读应看到有的爻写吉，有的写无不利，有的只讲行动条件，不能据此声称凡事谦让必获好报。全卦最值得讨论的是“劳谦”和“称物”：既有真实工作，也有相称判断。若用谦压低他人的正当需求，就与裒多益寡的方向相悖。</p><p><strong>细读线索</strong>：谦的阳爻在九三，正是劳谦所在；它位于下卦之终，上面仍有众阴，因而可以有劳而不处最高。这一结构适合帮助读者区分贡献与位置。六四用撝写谦的施行，六五与上六又出现强力行动，说明谦不只是把姿态放低。判断要看是否纠正不平、是否与责任相称。若不断说自己谦逊，却不做该承担的工作，仍没有触到劳谦与有终的实质。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%AC%99" target="_blank" rel="noopener noreferrer">《周易·谦》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E8%AC%99" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·谦》</a>。</p><h2 id="gua-16" tabindex="-1">16 豫：群体振奋也需要清醒 <a class="header-anchor" href="#gua-16" aria-label="Permalink to &quot;16 豫：群体振奋也需要清醒 {#gua-16}&quot;">​</a></h2><p><strong>卦符：䷏　上卦：震 ☳（雷、动）　下卦：坤 ☷（地、顺）。</strong></p><p><strong>卦辞原文</strong>：豫：利建侯行師。</p><p><strong>白话概括</strong>：豫有和乐、逸豫之义，顺而动，使众人响应。《正义》认为顺众而动可建立秩序，却也强调逸乐不可长久放纵，因此本卦不像某些卦那样列出元亨利贞四德。理解豫不能只抓快乐，也应读各爻怎样警惕自鸣、迟疑、沉迷和改过。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：鳴豫，凶。</td><td>因有所依恃而自鸣得意，快乐过早外扬，结果不利。与谦的鸣谦不同，关键在所鸣为何。</td></tr><tr><td>六二：介于石，不終日，貞吉。</td><td>坚定如石，察觉不合宜便及时调整，不拖到一整天。强调清楚分辨，不是处处抢快。</td></tr><tr><td>六三：盱豫，悔。遲有悔。</td><td>仰视追随以求快乐，又迟疑不决，两面皆可能后悔。“盱”的具体训释有异，宜保留不安自处的层次。</td></tr><tr><td>九四：由豫，大有得。勿疑，朋盍簪。</td><td>成为众人振奋所由，伙伴聚合。盍簪有聚合义及异文，不能只凭热烈响应证明目标正当。</td></tr><tr><td>六五：貞疾，恆不死。</td><td>处境受到压制，像长久有疾却未至灭亡。它描写政治与位置的张力，不是疾病诊断或寿命预言。</td></tr><tr><td>上六：冥豫，成有渝，无咎。</td><td>沉迷逸乐已经形成，若能够改变，仍可免咎。经文保留纠偏空间，并非错误一旦发生就无可挽回。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“雷出地奮，豫；先王以作樂崇德，殷薦之上帝，以配祖考。”</p><p><strong>解释</strong>：雷出大地而振奋，古人以音乐、祭祀表达共同敬意、彰显德业。“乐”是礼乐制度的一部分，不仅是个人娱乐。此处可用来理解声音、仪式与群体情绪如何相联。</p><p><strong>整体读法与误区</strong>：九四聚众与初六自鸣、上六冥豫相对照，显示振奋既能动员，也能遮蔽判断。六二在热闹中保持辨别，上六则承认沉迷之后仍可改。不能把“利行师”抽成任何群众激情的许可证；阅读的重点是行动的依据与纠偏能力，而非人越多、气氛越热烈就越正确。</p><p><strong>细读线索</strong>：豫的九四是唯一阳爻，处于震卦之初，成为古注所说众阴响应、由之而豫的位置。可是初六离它较远仍自鸣，六五居尊却受其刚强牵制，说明群体振奋不会让每个参与者处境相同。读者可以逐爻分辨谁在制造气氛、谁在依附气氛、谁有能力清醒退出。这样读会比把全卦统一译成快乐更贴近爻辞，也能解释为什么一卦之内多见悔与凶。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%AB" target="_blank" rel="noopener noreferrer">《周易·豫》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E8%B1%AB" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·豫》</a>。</p><h2 id="读后比较与自测" tabindex="-1">读后比较与自测 <a class="header-anchor" href="#读后比较与自测" aria-label="Permalink to &quot;读后比较与自测 {#读后比较与自测}&quot;">​</a></h2><ol><li>小畜上九为何在“既雨”之后反而警告征凶？履九五为何居正仍有厉？</li><li>泰上六和否上九怎样打破“一卦全吉或全凶”的读法？这是否等于现实必然自动翻转？</li><li>同人于宗为什么吝？“类族辨物”如何与共同相处并存？</li><li>大有九四、谦九三都涉及功业和自处，两者侧重点有什么不同？</li><li>谦之“鸣谦”与豫之“鸣豫”判断不同，为什么不能把同一个动词固定判成吉或凶？</li></ol><p>前篇：<a href="/life/personal/yijing/hexagrams-01-08">第 01—08 卦：乾坤至师比</a>。后篇：<a href="/life/personal/yijing/hexagrams-17-24">第 17—24 卦：随蛊至剥复</a>。返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',27)])])}const f=e(i,[["render",o]]);export{c as __pageData,f as default};
